      "porqueImporta": "A inserção de imagens, formas e objetos em tabelas do Word, com controle de disposição de texto, é objeto de avaliação em itens que avaliam a produção de documentos técnicos e relatórios. Erros comuns — usar envolvimento flutuante que faz a imagem escapar da célula, confundir objeto vinculado com incorporado, ou enviar por e-mail um relatório com vínculo quebrado — invertem o gabarito. Dominar envoltório, ordem de camadas, agrupamento e a diferença entre vínculo e incorporação é decisivo para responder corretamente.",
