        "versaoCorreta": "Incorreto: o objeto vinculado (Colar como linka) referência a fonte e exibe o conteúdo atualizado apenas enquanto o arquivo de origem estiver acessível; o envio por e-mail não transporta o vínculo funcional, diferentemente do objeto incorporado."
