      "porqueImporta": "O Slide Mestre é o ponto de controle central de uma apresentação do PowerPoint: define tipografia, cores, logotipos e os layouts filhos, de modo que qualquer alteração no mestre se propaga a todos os slides vinculados. Dominar esse recurso evita retrabalho de formatação slide a slide, garante identidade visual consistente e é requisito para produzir apresentações profissionais rapidamente em ambientes corporativos e de concurso.",
